#!/usr/bin/env bash
# Patch Omlet Arcade to use a local Longdan server.
#
# Usage:
#   scripts/patch-apk.sh /path/to/omlet-arcade-1-111-9.apk [host:port]
#
# The host defaults to the Waydroid host gateway (192.168.240.1:8080).
# The server public key is read from server/keys.json (generated by
# server/generate_keys.py).

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
APK="${1:-}"
HOST="${2:-192.168.240.1:8080}"

if [[ -z "$APK" || ! -f "$APK" ]]; then
  echo "usage: $0 /path/to/omlet-arcade.apk [host:port]" >&2
  exit 2
fi

APK="$(readlink -f "$APK")"
HOST_ONLY="${HOST%%:*}"
PYTHON="${PYTHON:-python3}"

find_bin() {
  local name="$1"
  if command -v "$name" >/dev/null 2>&1; then
    command -v "$name"
    return 0
  fi
  local candidate
  candidate="$(ls -1 /opt/android-sdk/build-tools/*/"$name" 2>/dev/null | sort -V | tail -1 || true)"
  if [[ -n "$candidate" ]]; then
    printf '%s\n' "$candidate"
    return 0
  fi
  return 1
}

APKTOOL="$(find_bin apktool || true)"
ZIPALIGN="$(find_bin zipalign || true)"
APKSIGNER="$(find_bin apksigner || true)"

for pair in "apktool:$APKTOOL" "zipalign:$ZIPALIGN" "apksigner:$APKSIGNER"; do
  name="${pair%%:*}"
  value="${pair#*:}"
  if [[ -z "$value" ]]; then
    echo "error: $name not found (install apktool/build-tools)" >&2
    exit 1
  fi
done

if ! command -v keytool >/dev/null 2>&1; then
  echo "error: keytool not found (install a JDK)" >&2
  exit 1
fi

KEYS="$ROOT/server/keys.json"
if [[ ! -f "$KEYS" ]]; then
  echo "server/keys.json not found; generating a new keypair..."
  "$PYTHON" "$ROOT/server/generate_keys.py"
fi

PUB="$("$PYTHON" -c 'import json,sys; print(json.load(open(sys.argv[1]))["public_b64"])' "$KEYS")"
if [[ -z "$PUB" ]]; then
  echo "error: could not read public_b64 from $KEYS" >&2
  exit 1
fi

WORK="$ROOT/build/apktool"
UNSIGNED="$ROOT/build/omlet-patched-unsigned.apk"
ALIGNED="$ROOT/build/omlet-patched-aligned.apk"
OUT="$ROOT/patched/omlet-patched-signed.apk"
KS="$ROOT/tools/debug.keystore"

rm -rf "$WORK"
mkdir -p "$ROOT/build" "$ROOT/patched" "$ROOT/tools"

echo "[1/6] decoding resources and manifest (no smali)..."
"$APKTOOL" d -f -s -o "$WORK" "$APK" >/dev/null

echo "[2/6] rewriting oml_pk.json..."
"$PYTHON" - "$WORK/res/raw/oml_pk.json" "$PUB" "$HOST" <<'PY'
import json
import sys

out, public_key, host = sys.argv[1:4]
clusters = ["ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE", "TEN"]
endpoint = f"http://{host}"
data = {
    "ClusterEndpoints": {name: [endpoint] for name in clusters},
    "ClusterKeys": {name: public_key for name in clusters},
    "DefaultCluster": "ONE",
    "IdpEndpoints": [endpoint],
    "IdpKey": public_key,
    "ReadOnlyKey": public_key,
    "ReadOnlyEndpoints": [endpoint],
}
with open(out, "w", encoding="utf-8") as fh:
    json.dump(data, fh, indent=2)
    fh.write("\n")
PY

echo "[3/6] allowing cleartext HTTP for $HOST_ONLY..."
cat > "$WORK/res/xml/network_security_config.xml" <<EOF
<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <base-config cleartextTrafficPermitted="true" />
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="true">127.0.0.1</domain>
        <domain includeSubdomains="true">$HOST_ONLY</domain>
        <domain includeSubdomains="true">dlblob.omlet.me</domain>
        <domain includeSubdomains="true">blobs.omlet.gg</domain>
        <domain includeSubdomains="true">cdn.stage.omapi.net</domain>
        <domain includeSubdomains="true">botcheck.stage.omapi.net</domain>
    </domain-config>
</network-security-config>
EOF

echo "[4/6] enabling guest account flow..."
"$PYTHON" - "$WORK/AndroidManifest.xml" <<'PY'
import sys

path = sys.argv[1]
with open(path, "r", encoding="utf-8") as fh:
    text = fh.read()

new = text.replace(
    'android:name="omlet.guest" android:value="false"',
    'android:name="omlet.guest" android:value="true"',
)
if new == text:
    print("warning: omlet.guest meta-data not found", file=sys.stderr)
text = new

new = text.replace(
    'android:usesCleartextTraffic="false"',
    'android:usesCleartextTraffic="true"',
)
if new == text:
    print("warning: usesCleartextTraffic not found", file=sys.stderr)
text = new

with open(path, "w", encoding="utf-8") as fh:
    fh.write(text)
PY

echo "[5/6] rebuilding, aligning and signing..."
"$APKTOOL" -JXmx6g b -j 1 -o "$UNSIGNED" "$WORK" >/dev/null

if [[ ! -f "$KS" ]]; then
  keytool -genkeypair \
    -keystore "$KS" -alias debug -keyalg RSA -keysize 2048 -validity 10000 \
    -storepass android -keypass android \
    -dname "CN=Android Debug,O=Android,C=US" >/dev/null 2>&1
fi

"$ZIPALIGN" -p -f 4 "$UNSIGNED" "$ALIGNED"
"$APKSIGNER" sign \
  --ks "$KS" --ks-key-alias debug \
  --ks-pass pass:android --key-pass pass:android \
  --out "$OUT" "$ALIGNED" >/dev/null
"$APKSIGNER" verify --verbose "$OUT" >/dev/null

if [[ "${KEEP_WORK:-0}" != "1" ]]; then
  rm -rf "$WORK"
fi

echo "[6/6] done: $OUT"
echo
echo "Reinstall it in Waydroid:"
echo "  sudo waydroid shell -- pm uninstall mobisocial.arcade || true"
echo "  adb install -r -d \"$OUT\""
echo
echo "Start the local server with:"
echo "  cd \"$ROOT/server\" && nohup ./venv/bin/python server.py >> ../logs/server.log 2>&1 &"
